 var k=p.person,r=random(l,p.id+':profile'),edu=k.education170&&k.education170.skills||{};
 if(!k.dynasty908)k.dynasty908={management:clamp(k.management139!=null?k.management139:edu.management!=null?edu.management:(k.study==null?(k.st&&k.st.kno||50):k.study)*.45+Math.min(20,Math.max(0,p.age-18))),reputation:clamp(k.professional163==null?45:k.professional163),ambition:clamp(k.persona141&&k.persona141.traits&&k.persona141.traits.ambition!=null?k.persona141.traits.ambition:30+r()*40),endorsements:{},history:[]};
