function pageRows(l,arg,all,id,make){var page=Math.max(0,Math.floor(arg.page||0)),out=all.slice(page*35,page*35+35).map(make);if(page)out.push({k:'prev',l:'Trang trước',run:function(l,r){X.next(l,id,r,Object.assign({},arg,{page:page-1}));}});if(all.length>(page+1)*35)out.push({k:'next',l:'Trang tiếp',run:function(l,r){X.next(l,id,r,Object.assign({},arg,{page:page+1}));}});return out;}
