X.menu('dynasty908','Gia tộc, nhánh con và hồ sơ người kế vị',adult,'Mỗi người giữ mong muốn, quan hệ và tài sản riêng. Con chung, con ngoài hôn nhân và con nuôi có thể gắn bó hoặc bất đồng; xuất thân không quyết định năng lực. Cổ phần không tự trao chức vụ.',function(l,a){var out=pageRows(l,a,people(l),'dynasty908',function(p){return{k:p.id,l:p.name+' · '+p.age+' tuổi'+((l.kids||[]).includes(p.person)?' · '+branchText(l,p.person):''),run:function(l,r){X.next(l,'heirProfile908',r,{id:p.id});}};});out.push({k:'claims',l:'Thông tin cần xác minh về người con khác · '+state(l).claims.filter(function(c){return !c.closed;}).length,run:function(l,r){X.next(l,'childClaims908',r);}},{k:'vote',l:'Ứng cử CEO/chủ tịch và biểu quyết',run:function(l,r){X.next(l,'governance908',r);}},{k:'review',l:'Yêu cầu xem xét kế hoạch tài sản / hòa giải thừa kế',run:function(l,r){X.next(l,'inheritanceReview908',r);}});return out;},18,'Tình cảm & gia đình');
X.menu('heirProfile908','Hồ sơ người kế vị và quan hệ gia tộc',adult,function(l,d){var p=find(l,d.arg.id);return p?summary(l,p):'Người này không còn trong hồ sơ còn sống.';},function(l,a){var p=find(l,a.id);if(!p)return[];var q=profile(l,p),out=[{k:'support',l:'Vận động cha mẹ, ông bà, người thân hoặc cổ đông',why:p.age>=16?true:'Từ 16 tuổi mới tham gia bàn kế nghiệp',run:function(l,r){X.next(l,'heirSupport908',r,a);}},{k:'project',l:'Nhận dự án quản trị / công ty con',why:p.age>=18?true:'Cần đủ 18 tuổi',run:function(l,r){X.next(l,'heirProject908',r,a);}},{k:'alliance',l:'Bàn liên minh với người thân trưởng thành',why:p.age>=18?true:'Cần đủ 18 tuổi',run:function(l,r){X.next(l,'alliance908',r,a);}},{k:'education',l:'Đào tạo quản trị dài hạn qua cố vấn',run:function(l,r){X.next(l,'education170',r);}}];if((l.kids||[]).includes(p.person))out.push({k:'family',l:'Công nhận, gặp gỡ và giới thiệu với gia đình',run:function(l,r){X.next(l,'childBranch908',r,a);}},{k:'allowance',l:'Chu cấp thường xuyên, giáo dục và quỹ riêng',run:function(l,r){X.next(l,'allowance908',r,a);}});out.push({k:'social',l:'Dạ tiệc, câu lạc bộ và giới thiệu đối tác',why:p.age>=18?true:'Cần trưởng thành',run:function(l,r){X.next(l,'heirSocial908',r,a);}},{k:'review',l:'Ghi nhận ý kiến về sự công bằng trong kế hoạch tài sản',run:function(l,r){X.next(l,'inheritanceReview908',r,{id:p.id});}});return out;},18);
function supporters(l){var out=people(l).filter(function(p){return p.age>=18;});['f','m'].forEach(function(k){if(l.fam[k+'Alive']&&!(k==='f'&&l.fam.noDad))out.push({id:'parent:'+k,name:l.fam[k+'Name']||(k==='f'?'Bố':'Mẹ'),age:l.age+(l.fam[k+'Age']||25),kind:'cha mẹ'});});(Array.isArray(l.gp)?l.gp:[]).forEach(function(p){if(p.alive!==false)out.push({id:X.uid(l,p),name:p.name||p.n||'Ông bà',person:p,age:p.age||60,kind:'ông bà'});});B.companies(l).filter(function(c){return !c.merged;}).forEach(function(c){(c.holders137||[]).forEach(function(h){if(!out.some(function(p){return p.id===h.id;}))out.push({id:h.id,name:h.name,kind:'cổ đông',age:18});});});return out;}
X.menu('heirSupport908','Vận động sự ủng hộ',adult,'Mỗi ứng viên gặp mỗi người một lần/năm. Sự ủng hộ có hiệu lực ba năm, không đổi cổ phần hay buộc người ấy bỏ phiếu bất chấp năng lực.',function(l,a){var p=find(l,a.id);if(!p)return[];var q=profile(l,p);return pageRows(l,a,supporters(l).filter(function(v){return v.id!==p.id;}),'heirSupport908',function(v){return{k:v.id,l:'Trình bày kế hoạch với '+v.name+' · '+v.kind,why:q.endorsements[v.id]&&q.endorsements[v.id].at===l.age?'Đã trao đổi năm nay':true,run:function(l,r,log){if(q.endorsements[v.id]&&q.endorsements[v.id].at===l.age)return;var close=relation(l,p.id,v.id),chance=U.clamp(.1+close/250+q.reputation/400+q.management/400,.05,.9),ok=r()<chance;q.endorsements[v.id]={at:l.age,ok:ok};relation(l,p.id,v.id,ok?3:-1);note(l,p,(ok?'Được ':'Chưa thuyết phục được ')+v.name+' ủng hộ');log(v.name+(ok?' đồng ý ủng hộ '+p.name+' sau khi xem kế hoạch.':' chưa tin kế hoạch của '+p.name+'; cần thêm thành tích.'),'neutral');}};});},18);
