function merit(l,p,plan,e){var q=profile(l,p),v=q.management*.55+q.reputation*.35+(plan==='rescue'?q.management*.1:q.ambition*.1);if(plan==='rescue'&&e.company&&!(e.company.lastProfit<0||T.ensure(l,e.company).debt>0))v-=8;return v;}
