X.menu('governanceCompany908','Ứng viên, kế hoạch và phiếu bầu',adult,function(l,d){var e=entity(l,d.arg.cid);if(!e)return 'Doanh nghiệp không còn trong phạm vi gia đình.';var s=governanceState(e);return e.name+'\n'+voters(l,e).map(function(v){return v.name+': '+Math.round(v.share*100)/100+'% phiếu';}).join(' · ')+'\n'+Object.keys(s.nominations).map(function(k){var n=s.nominations[k];return n.name+' ứng cử '+k+' — '+PLANS[n.plan]+'; mở phiếu từ tuổi '+(n.at+1);}).join('\n')+'\n'+s.history.slice(-3).map(function(h){return h.name+': '+h.votes.toFixed(1)+'% '+(h.won?'trúng cử':'chưa đạt');}).join('\n');},function(l,a){var e=entity(l,a.cid);if(!e)return[];var out=pageRows(l,a,people(l).filter(function(p){return p.age>=18&&(!e.family||p.id==='self'||(l.sibList||[]).includes(p.person));}),'governanceCompany908',function(p){return{k:p.id,l:'Xem kế hoạch ứng cử của '+p.name,run:function(l,r){X.next(l,'governancePlan908',r,{cid:a.cid,id:p.id});}};});['ceo','chair'].forEach(function(role){var n=governanceState(e).nominations[role];if(n)out.push({k:'vote:'+role,l:'Mở phiếu '+(role==='ceo'?'CEO':'chủ tịch')+' cho '+n.name,why:l.age>n.at?true:'Cần ít nhất một năm để xem xét kế hoạch',run:function(l,r,log){vote(l,e,role,log);}});});return out;},18);
X.menu('governancePlan908','Kế hoạch kinh doanh và chức vụ ứng cử',adult,'CEO điều hành hoạt động; chủ tịch chủ trì quản trị. Hai vị trí được bầu riêng. Người không muốn nhận trách nhiệm có thể từ chối.',function(l,a){var e=entity(l,a.cid),p=find(l,a.id);if(!e||!p)return[];var out=[];['ceo','chair'].forEach(function(role){Object.keys(PLANS).forEach(function(plan){var existing=governanceState(e).nominations[role];out.push({k:role+':'+plan,l:(role==='ceo'?'CEO':'Chủ tịch')+' · '+PLANS[plan],why:!willing(l,p)?'Người này muốn theo con đường riêng':existing?'Đã có hồ sơ ứng cử, chờ biểu quyết':true,run:function(l,r,log){if(governanceState(e).nominations[role])return;if(nominate(l,e,p,role,plan))log('Ghi hồ sơ '+p.name+' ứng cử '+role+' với kế hoạch '+PLANS[plan]+'. Chưa trao quyền; có thể vận động trước đợt biểu quyết năm sau.','neutral');}});});});return out;},18);
X.menu('heirProject908','Chứng minh năng lực bằng dự án',adult,'Dự án kéo dài hai năm, dùng ngân sách doanh nghiệp khi được chủ sở hữu chấp thuận. Có báo cáo từng năm, lợi nhuận hoặc lỗ thực trong sổ công ty; không cộng giá trị công ty thành tiền cá nhân.',function(l,a){var p=find(l,a.id);if(!p||p.age<18)return[];var q=profile(l,p);return entities(l).filter(function(e){return e.company&&e.company.share>50||e.family;}).flatMap(function(e){return Object.keys(PLANS).map(function(plan){var cost=e.company?Math.min(l.base*.5,e.company.value*.01):l.base*.1;return{k:e.id+':'+plan,l:e.name+' · '+PLANS[plan]+' · vốn '+H.money(l,cost),why:q.project&&q.project.status==='active'?'Đang có dự án':!willing(l,p)?'Người này chưa muốn nhận dự án':true,run:function(l,r,log){if(q.project&&q.project.status==='active'||!willing(l,p))return;var owner=e.family?supporters(l).some(function(v){return v.kind==='cha mẹ'&&q.endorsements[v.id]&&q.endorsements[v.id].ok;}):true;if(!owner){log('Cần thuyết phục ít nhất một phụ huynh đang giữ quyền quản lý trước khi nhận ngân sách.','neutral');return;}if(e.company?!T.spend(l,e.company,cost,'Dự án kế nghiệp '+p.name):!pay(l,cost,'Thực tập và dự án doanh nghiệp bố mẹ')){log('Chưa đủ ngân sách; không mở dự án.','neutral');return;}q.project={title:PLANS[plan],cid:e.id,at:l.age,due:l.age+2,progress:0,score:0,cost:cost,plan:plan,status:'active',rolls:[r(),r()]};note(l,p,'Nhận dự án '+PLANS[plan]);log(p.name+' bắt đầu '+PLANS[plan]+' tại '+e.name+'. Ngân sách đã trừ, kết quả chưa được quyết định ngay.','neutral');}};});});},18);
X.menu('alliance908','Thỏa thuận liên minh và quyền lợi',adult,'Hai người trưởng thành có thể ủng hộ nhau trong kế nghiệp. Liên minh không chuyển cổ phần, không tước quyền người thứ ba; bất đồng về chức vụ hoặc quyền lợi có thể làm liên minh tan rã.',function(l,a){var p=find(l,a.id);if(!p||p.age<18)return[];return pageRows(l,a,people(l).filter(function(v){return v.age>=18&&v.id!==p.id;}),'alliance908',function(v){var old=state(l).coalitions.find(function(c){return c.active&&c.members.includes(p.id)&&c.members.includes(v.id);});return{k:v.id,l:(old?'Chấm dứt liên minh với ':'Đề nghị cùng ủng hộ '+p.name+' với ')+v.name,run:function(l,r,log){if(old){old.active=false;old.end=l.age;log('Hai người chấm dứt thỏa thuận ủng hộ. Cổ phần riêng giữ nguyên.','neutral');return;}var q=profile(l,p);q.allianceAt=q.allianceAt||{};if(q.allianceAt[v.id]===l.age)return;q.allianceAt[v.id]=l.age;if(r()>=.15+relation(l,p.id,v.id)/150){log(v.name+' muốn giữ lập trường độc lập.','neutral');return;}state(l).coalitions.push({members:[p.id,v.id],leader:p.id,at:l.age,active:true,ambitions:[q.ambition,profile(l,v).ambition],rights:[stake(l,p.id),stake(l,v.id)]});relation(l,p.id,v.id,8);log(p.name+' và '+v.name+' đồng ý ủng hộ nhau, cùng đề xuất '+p.name+' điều hành. Các thành viên khác vẫn có quyền ứng cử và hưởng tài sản.','neutral');}};});},18);
function rememberContact(l,p){if(l.sex!=='M'||!p||p.alive===false||p.age<18||l.age<18||p.sex===l.sex)return;var s=state(l),id=E.RELATIONS108.person(l,p),old=s.contacts.find(function(c){return c.id===id;});if(!old)s.contacts.push({id:id,parent:copy(p),at:l.age,born:l.age+1,checked:false});}
function createClaim(l,contact,r){var s=state(l),id='claim908:'+l.id+':'+(++s.serial),sex=r()<.5?'M':'F',age=l.age-contact.born;if(age<0||l.kids.some(function(k){return k.born===contact.born&&k.coParent108&&k.coParent108.id===contact.id;}))return null;var p={name:H.stranger(l,r,sex),sex:sex,born:contact.born,alive:true,adopted:false,married:false,kids:0,vac:true,close:25,study:40+Math.floor(r()*30),edu:age>=22?5:age>=18?3:age>=15?2:age>=11?1:0,coParent108:{id:contact.id,name:contact.parent.name,sex:contact.parent.sex},mate:{name:contact.parent.name,sex:contact.parent.sex,age:Math.max(18,(contact.parent.age||25)+1)},mateInc:contact.parent.inc||0,birthContext108:'outside',custody:'other',residence112:contact.parent.residence108||l.place};X.uid(l,p);var c={id:id,person:p,parent:copy(contact.parent),at:l.age,evidence:0,truth:r()<.75,closed:false,consent:r()<.85,history:[]};s.claims.push(c);return c;}
function claim(l,id){return state(l).claims.find(function(c){return c.id===id;});}
function verify(l,c,r,log){if(adult(l)!==true||!c||c.closed||c.verifyAt===l.age)return false;if(!c.consent){log('Người trực tiếp nuôi dưỡng chưa đồng ý cung cấp hồ sơ. Bạn có thể giữ liên lạc, không ép buộc xác minh.','neutral');c.verifyAt=l.age;return false;}if(!pay(l,l.base*.015,'Đối chiếu hồ sơ quan hệ gia đình'))return false;c.verifyAt=l.age;c.evidence++;c.history.push({age:l.age,type:'verify'});if(c.evidence<2){log('Đã đối chiếu thông tin ban đầu. Cần làm việc tiếp vào năm sau; chưa kết luận quan hệ cha mẹ – con.','neutral');return true;}c.closed=true;c.confirmed=c.truth;if(!c.truth){log('Kết quả đối chiếu không xác nhận quan hệ cha mẹ – con. Không đưa người này vào danh sách con hoặc tự chia tài sản.','neutral');return true;}var p=c.person;if(!l.kids.some(function(k){return X.uid(l,k)===X.uid(l,p);}))l.kids.push(p);p.family108Known=true;p.branch908={kind:'outside',confirmed:true,acknowledged:false,public:false,caregiver:{id:c.parent.relation108||'',name:c.parent.name,sex:c.parent.sex},wish:random(l,c.id+':wish')()<.7?'connect':'independent',home:'other',history:[{year:l.birthYear+l.age,text:'Quan hệ được xác minh sau hai đợt đối chiếu'}],at:l.age};c.childId=X.uid(l,p);log('Quan hệ với '+p.name+' được xác nhận. Con đang có cuộc sống riêng cùng '+c.parent.name+'. Bạn có thể gặp gỡ, công nhận, hỗ trợ và bàn việc giới thiệu với gia đình; quyền tài sản không phụ thuộc việc công khai.','big');return true;}
X.menu('childClaims908','Thông tin về người con cần xác minh',adult,'Thông báo từ người cũ chưa phải kết luận quan hệ cha mẹ – con. Người đang nuôi dưỡng có quyền đồng ý hoặc từ chối đối chiếu. Hồ sơ xác nhận cần hai đợt, không bấm lặp trong cùng năm.',function(l,a){return pageRows(l,a,state(l).claims,'childClaims908',function(c){return{k:c.id,l:c.person.name+' · '+(l.age-c.person.born)+' tuổi · '+(c.closed?(c.confirmed?'đã xác nhận':'không xác nhận'):'đang xác minh '+c.evidence+'/2'),run:function(l,r){X.next(l,'childClaim908',r,{id:c.id});}};});},18);
X.menu('childClaim908','Gặp gỡ, đối chiếu và hỗ trợ',adult,function(l,d){var c=claim(l,d.arg.id);return c?c.parent.name+' cho biết '+c.person.name+' có thể là con của bạn. Người này '+(l.age-c.person.born)+' tuổi, đang sống tại '+c.person.residence112+'. '+(c.closed?(c.confirmed?'Đã xác nhận quan hệ.':'Kết quả không xác nhận quan hệ.'):'Chưa xác định quan hệ; '+c.evidence+'/2 đợt đối chiếu.'):'Hồ sơ không còn.';},function(l,a){var c=claim(l,a.id);if(!c)return[];if(c.closed)return c.confirmed?[{k:'open',l:'Mở hồ sơ người con đã xác nhận',run:function(l,r){X.next(l,'childBranch908',r,{id:c.childId});}}]:[];return[{k:'verify',l:'Đề nghị đối chiếu quan hệ · '+H.money(l,l.base*.015),why:c.verifyAt===l.age?'Đã làm việc năm nay':true,run:function(l,r,log){verify(l,c,r,log);}},{k:'meet',l:'Gặp riêng, nghe câu chuyện của người trực tiếp nuôi dưỡng',why:c.meetAt===l.age?'Đã gặp năm nay':true,run:function(l,r,log){c.meetAt=l.age;if(!c.consent&&r()<.5)c.consent=true;c.person.close=clamp(c.person.close+3);c.refused=false;log('Bạn lắng nghe '+c.parent.name+' và '+c.person.name+'. Chưa tự kết luận quan hệ huyết thống.','neutral');}},{k:'help',l:'Tự nguyện hỗ trợ nhu cầu học tập · '+H.money(l,l.base*.05),why:c.helpAt===l.age?'Đã hỗ trợ năm nay':true,run:function(l,r,log){if(c.helpAt===l.age||!pay(l,l.base*.05,'Hỗ trợ người đang cần đối chiếu quan hệ'))return;c.helpAt=l.age;E.RELATIVE163.post(l,c.person,l.base*.05,'Hỗ trợ tự nguyện trước khi xác định quan hệ','claim:'+c.id+':'+l.age);log('Khoản hỗ trợ được ghi vào tiền riêng của '+c.person.name+', không được đổi lấy xác nhận quan hệ hoặc quyền thừa kế.','neutral');}},{k:'decline',l:'Từ chối liên lạc lúc này',run:function(l,r,log){c.refused=true;c.person.close=clamp(c.person.close-8);c.contactAfter=l.age+3;log(c.person.name+' và người chăm sóc ghi nhận quyết định, có thể giữ khoảng cách. Hồ sơ chưa tự biến thành quan hệ đã được công nhận.','neutral');}}];},18);
function introduce(l,p,r,log,manual){var b=branch(l,p.person);if(b.public)return false;b.public=true;b.history.push({year:l.birthYear+l.age,text:'Được giới thiệu với gia đình'});var s=state(l),sp=l.partner;if(sp&&sp.alive!==false&&sp.status==='married'&&p.person.birthContext108==='outside'){var key=E.RELATIONS108.person(l,sp);b.spouse=key;sp.affection108=clamp((sp.affection108==null?60:sp.affection108)-15);s.reaction={child:p.id,spouse:key,at:l.age,trust:Math.round(sp.affection108),resolved:false};X.next(l,'familyReaction908',r,{id:p.id,spouse:key},{manual:manual!==false});}children(l).forEach(function(v){if(v.id===p.id)return;var q=profile(l,v),jealous=q.ambition>65&&r()<.5;relation(l,v.id,p.id,jealous?-8:5);note(l,v,jealous?'Lo lắng về sự quan tâm và cơ hội trong gia đình':'Làm quen với '+p.name);});log('Gia đình được giới thiệu với '+p.name+'. Mỗi người có phản ứng riêng; người trực tiếp nuôi dưỡng vẫn có quyền giữ khoảng cách.','neutral');return true;}
X.menu('childBranch908','Công nhận con và xây dựng quan hệ',adult,function(l,d){var p=find(l,d.arg.id);return p?summary(l,p)+'\nCon mong muốn: '+(branch(l,p.person).wish==='independent'?'giữ cuộc sống tự lập':'được gặp gỡ, công nhận và xây dựng quan hệ'):'Người con không còn trong danh sách còn sống.';},function(l,a){var p=children(l).find(function(p){return p.id===a.id;});if(!p)return[];var k=p.person,b=branch(l,k);return[{k:'ack',l:'Công nhận quan hệ cha/mẹ – con',why:b.acknowledged?'Đã công nhận':true,run:function(l,r,log){b.acknowledged=true;note(l,p,'Được cha/mẹ công nhận');k.close=clamp((k.close||30)+8);log('Bạn công nhận '+p.name+', sẵn sàng gặp gỡ và hỗ trợ. Chưa tự đổi nơi ở của con hoặc công khai với cả gia đình.','good');}},{k:'private',l:'Giữ thông tin riêng tư, tiếp tục hỗ trợ',why:b.public?'Gia đình đã biết, không thể xóa ký ức bằng lựa chọn này':true,run:function(l,r,log){if(b.public)return;b.privateAt=l.age;log('Bạn chọn giữ kín lúc này. Trách nhiệm hỗ trợ vẫn còn và thông tin có thể được biết đến sau này.','neutral');}},{k:'meet',l:'Thăm nom, dự cột mốc hoặc tặng quà · '+H.money(l,l.base*.01),why:b.meetAt===l.age?'Đã dành thời gian năm nay':true,run:function(l,r,log){if(b.meetAt===l.age||!pay(l,l.base*.01,'Gặp gỡ và tặng quà '+p.name))return;b.meetAt=l.age;if(b.wish==='independent'&&r()<.5){log(p.name+' muốn giữ khoảng cách lúc này; bạn tôn trọng quyết định.','neutral');return;}k.close=clamp((k.close||30)+5);note(l,p,'Cùng cha/mẹ dự một cột mốc cá nhân');log('Bạn dành thời gian với '+p.name+', hỏi về việc học, công việc và cuộc sống riêng.','good');}},{k:'introduce',l:'Giới thiệu với bạn đời, các con và họ hàng',why:!b.acknowledged?'Cần công nhận quan hệ trước':b.public?'Gia đình đã biết':true,run:function(l,r,log){if(b.acknowledged)introduce(l,p,r,log);}},{k:'home',l:'Bàn việc sống cùng gia đình',why:!b.public?'Cần trao đổi công khai trước':b.home==='family'?'Đã sống cùng':true,run:function(l,r,log){if(!b.public||b.moveAt===l.age)return;b.moveAt=l.age;var consent=b.wish==='connect'&&r()<.6;if(!consent){log(p.name+' hoặc người trực tiếp chăm sóc muốn giữ chỗ ở hiện tại. Không tự chuyển quyền chăm sóc.','neutral');return;}b.home='family';k.custody='both';k.residence112=l.city||l.place;note(l,p,'Thỏa thuận sống cùng gia đình');log('Sau khi các bên đồng thuận, '+p.name+' chuyển về sống cùng gia đình.','good');}},{k:'support',l:'Thiết lập chu cấp và quỹ riêng',run:function(l,r){X.next(l,'allowance908',r,a);}},{k:'distance',l:'Không tiếp tục liên lạc lúc này',run:function(l,r,log){b.wish='independent';k.close=clamp((k.close||30)-8);note(l,p,'Chọn giữ khoảng cách sau khi bị từ chối liên lạc');log(p.name+' giữ cuộc sống riêng. Quyết định này không tự xóa quan hệ đã xác nhận hoặc tài sản của con.','neutral');}}];},18);
X.menu('familyReaction908','Gia đình đối diện thông tin mới',adult,function(l,d){var p=find(l,d.arg.id);return p?'Người bạn đời muốn bạn giải thích về '+p.name+', trách nhiệm chăm sóc và cách phân chia sự quan tâm. Mất niềm tin có thể dẫn tới tư vấn, tạm ly thân hoặc ly hôn; không mặc định phản ứng của mọi gia đình giống nhau.':'Hoàn cảnh đã thay đổi.';},function(l,a){var s=state(l),sp=l.partner,ev=s.reaction;if(!ev||ev.resolved||!sp||sp.alive===false||sp.relation108!==a.spouse||ev.child!==a.id)return[];return[{k:'honest',l:'Nói rõ quá khứ, trách nhiệm và cùng lập ngân sách công bằng',run:function(l,r,log){ev.resolved=true;ev.path='counsel';ev.due=l.age+1;ev.roll=r();log('Hai người bắt đầu trao đổi và tư vấn. Niềm tin cần thời gian, chưa được khôi phục ngay.','neutral');}},{k:'space',l:'Tôn trọng đề nghị tạm sống riêng để suy nghĩ',run:function(l,r,log){ev.resolved=true;ev.path='separate';ev.due=l.age+1;ev.roll=r();sp.separated908=true;log('Hai người tạm sống riêng; hôn nhân, nghĩa vụ chăm sóc và tài sản chưa tự chấm dứt.','neutral');}},{k:'divorce',l:'Cùng giải quyết ly hôn và nghĩa vụ với các con',run:function(l,r){ev.resolved=true;X.next(l,'divorce',r);}},{k:'deny',l:'Né tránh cuộc đối thoại',run:function(l,r,log){ev.resolved=true;ev.path='avoid';ev.due=l.age+1;ev.roll=r();sp.affection108=clamp((sp.affection108||50)-10);log('Việc né tránh khiến niềm tin giảm thêm; vấn đề chưa được giải quyết.','bad');}}];},18);
var TIERS={basic:{n:'Chu cấp theo điều kiện gia đình',factor:.12},elite:{n:'Thượng lưu',usd:50000},heir:{n:'Người thừa kế',usd:150000}};
function annual(l,tier){var t=TIERS[tier];return t?t.usd?usd(l,t.usd*12):l.base*t.factor:0;}
function fundAllowance(l,p,log){var q=profile(l,p),a=q.allowance;if(!a||!a.active||a.paidAt===l.age||p.person.alive===false)return false;var n=annual(l,a.tier);a.paidAt=l.age;if(!pay(l,n,'Chu cấp '+TIERS[a.tier].n+' cho '+p.name)){a.active=false;a.stopped=l.age;log('Tạm dừng chu cấp '+p.name+' vì thiếu tiền mặt và quỹ dự phòng. Không tự vay hay rút tiền công ty.','neutral');return false;}var k=p.person,st=k.support114||(k.support114={balance:0});var service=a.tier==='basic'?0:.3;st.balance=(st.balance||0)+n*(1-service);a.total=(a.total||0)+n;a.history=a.history||[];a.history.push({year:l.birthYear+l.age,amount:n,fund:n*(1-service),services:n*service});if(service){var edu=k.education170||(k.education170={courses:[],skills:{},history:[]});if(p.age>=6&&willing(l,p))edu.skills.management=clamp((edu.skills.management||0)+1);note(l,p,'Được chi trả học tập, giao lưu, chuyến đi và hỗ trợ cá nhân trong năm');}log('Chu cấp '+p.name+': '+H.money(l,n*(1-service))+' vào quỹ riêng'+(service?', '+H.money(l,n*service)+' chi cho học tập, du lịch, giao lưu và hỗ trợ cá nhân.':'.')+' Khoản quỹ chưa tiêu không cộng lần nữa vào tiền riêng.','neutral');return true;}
X.menu('allowance908','Chu cấp cho con và điều kiện gia đình',adult,function(l,d){var p=find(l,d.arg.id),q=p&&profile(l,p),a=q&&q.allowance;return (p?p.name:'Người con')+' · '+(a&&a.active?'Đang bật '+TIERS[a.tier].n:'Chưa bật chu cấp định kỳ')+'. Game kết toán theo năm: 12 tháng trả một lần, năm đăng ký trả ngay. Gói cao cấp yêu cầu tài sản ròng ít nhất 5 lần ngân sách năm và đủ tiền mặt; 70% vào quỹ riêng, 30% chi dịch vụ. Nhà riêng được chuyển qua mục tặng tài sản, không tặng kèm từ hư không.';},function(l,a){var p=children(l).find(function(p){return p.id===a.id;});if(!p)return[];var q=profile(l,p),out=Object.keys(TIERS).map(function(tier){var n=annual(l,tier),t=TIERS[tier];return{k:tier,l:t.n+(t.usd?' · '+t.usd.toLocaleString('en-US')+' USD/tháng':'')+' · '+H.money(l,n)+'/năm',why:q.allowance&&q.allowance.paidAt===l.age?'Đã thanh toán năm nay; đổi gói từ năm sau':t.usd&&!rich(l,n)?'Chưa đủ tài sản hoặc dòng tiền cho gói cao cấp':l.money<n+l.base*.1?'Chưa đủ ngân sách':true,run:function(l,r,log){if(q.allowance&&q.allowance.paidAt===l.age||t.usd&&!rich(l,n))return;q.allowance={tier:tier,active:true,at:l.age,history:[]};fundAllowance(l,p,log);}};});out.push({k:'off',l:'Dừng tự động chu cấp từ năm tiếp theo',run:function(l,r,log){if(q.allowance)q.allowance.active=false;log('Đã dừng tự động chu cấp; tiền đã chuyển vẫn thuộc quỹ của con.','neutral');}},{k:'home',l:'Tặng nhà hoặc tài sản riêng từ tài sản đang có',run:function(l,r){X.next(l,'gift112',r);}},{k:'education',l:'Chọn chương trình giáo dục tinh hoa dài hạn',run:function(l,r){X.next(l,'education170',r);}},{k:'staff',l:'Thuê trợ lý / bảo vệ cho gia đình',run:function(l,r){X.next(l,'staff113',r);}});return out;},18);
X.menu('inheritanceReview908','Đề nghị xem xét tài sản và di chúc',adult,'Ý kiến về sự công bằng không tự thay đổi di chúc hoặc tước tài sản của người khác. Khi cha mẹ còn sống, đây là đề nghị đối thoại. Sau thừa kế, hòa giải chỉ chuyển khoản tiền mà người thừa kế khác tự nguyện có khả năng đóng góp; hồ sơ và kết quả cần thời gian.',function(l,a){var origin=l.flags.origin908,p=a.id&&find(l,a.id),s=state(l),open=s.reviews.some(function(c){return c.status==='open';});return[{k:'request',l:'Yêu cầu đối chiếu cách chia và tổ chức đối thoại',why:open?'Đã có hồ sơ đang xem xét':s.reviewAt===l.age?'Đã gửi yêu cầu năm nay':true,run:function(l,r,log){if(s.reviewAt===l.age||s.reviews.some(function(c){return c.status==='open';}))return;s.reviewAt=l.age;s.reviews.push({at:l.age,due:l.age+1,status:'open',claimant:p?p.id:'self',estate:!!(origin&&origin.parentDead),evidence:0,roll:r(),name:p?p.name:l.name});log('Đã ghi yêu cầu xem xét. Chưa sửa di chúc hoặc chuyển tiền; có thể bổ sung thông tin và chờ trao đổi năm sau.','neutral');}},{k:'evidence',l:'Bổ sung hồ sơ và nhu cầu thực tế',why:!open?'Chưa có hồ sơ đang xem xét':s.evidenceAt===l.age?'Đã bổ sung năm nay':true,run:function(l,r,log){var c=s.reviews.find(function(c){return c.status==='open';});if(!c||s.evidenceAt===l.age)return;s.evidenceAt=l.age;c.evidence++;log('Bổ sung thông tin tài sản, nhu cầu học tập và việc chăm sóc; không giả định người có ít tài sản hơn chắc chắn thắng tranh chấp.','neutral');}},{k:'will',l:'Xem / lập di chúc đối với tài sản của chính mình',run:function(l,r){X.next(l,'di_chuc',r);}}];},18);
function joint(l,a,b,r,log){if(a.age<18||b.age<18||!willing(l,a)||!willing(l,b))return false;var n=l.base*.2,pa=a.person,pb=b.person;if(pa.savings158<n||pb.savings158<n||pa.venture163&&pa.venture163.status==='operating'||pb.venture163&&pb.venture163.status==='operating')return false;var token='joint908:'+l.id+':'+l.age+':'+[a.id,b.id].sort().join(':'),roll=r()<U.clamp(.2+(profile(l,a).management+profile(l,b).management)/300,.1,.85);if(!E.RELATIVE163.post(l,pa,-n,'Vốn dự án chung với '+b.name,token))return false;if(!E.RELATIVE163.post(l,pb,-n,'Vốn dự án chung với '+a.name,token)){E.RELATIVE163.post(l,pa,n,'Hoàn vốn dự án chưa mở',token+':refund');return false;}[a,b].forEach(function(p){p.person.venture163={title:'Dự án chung '+a.name+' & '+b.name,capital:n,started:l.age,due:l.age+3,status:'operating',success:roll,joint908:token};});relation(l,a.id,b.id,10);log(a.name+' và '+b.name+' góp mỗi người '+H.money(l,n)+' từ tiền riêng, bắt đầu dự án kinh doanh chung ba năm. Kết quả và tiền thu hồi được ghi riêng cho mỗi người.','big');return true;}
function eventChoices(l){var cs=children(l).filter(function(p){return p.age>=10;}),out=[];for(var i=0;i<cs.length;i++)for(var j=i+1;j<cs.length;j++){var a=cs[i],b=cs[j],base={a:a.id,b:b.id};out.push(Object.assign({type:'dinner'},base),Object.assign({type:'bond'},base));if(state(l).claims.some(function(c){return !c.closed;}))out.push(Object.assign({type:'inquiry'},base));if((branch(l,a.person).kind==='outside'&&branch(l,a.person).public)||(branch(l,b.person).kind==='outside'&&branch(l,b.person).public))out.push(Object.assign({type:'outsider'},base));var ach=[a,b].find(function(p){return (p.person.persona141&&p.person.persona141.milestones||[]).length||p.person.edu>=5;});if(ach)out.push(Object.assign({type:'birthday',ach:ach.id},base));if(a.age>=18&&b.age>=18){if(a.person.edu>=5&&b.person.edu<5||b.person.edu>=5&&a.person.edu<5)out.push(Object.assign({type:'university'},base));if(!a.person.married&&!b.person.married&&!a.person.partner&&!b.person.partner&&!a.person.romance908&&!b.person.romance908)out.push(Object.assign({type:'romance'},base));if(a.person.savings158>=l.base*.2&&b.person.savings158>=l.base*.2)out.push(Object.assign({type:'venture'},base));}if(a.age>=16&&a.age<=24&&b.age>=16&&b.age<=24&&(a.person.study>=70||b.person.study>=70))out.push(Object.assign({type:'scholarship'},base));if(E.netWorth(l)>=usd(l,5000000))out.push(Object.assign({type:'auction'},base));if((a.person.gifts112||[]).some(function(g){return g.kind==='home';})!==(b.person.gifts112||[]).some(function(g){return g.kind==='home';}))out.push(Object.assign({type:'home'},base));}return out;}
function eventText(l,e){var a=find(l,e.a),b=find(l,e.b);if(!a||!b)return 'Các nhân vật trong cuộc gặp đã thay đổi.';var t={inquiry:a.name+' nghi ngờ mình còn anh chị em khác từ thông tin người cũ đang gửi. '+b.name+' muốn tìm hiểu cùng; gia đình cần đối chiếu hồ sơ, chưa thể coi lời đồn là kết luận.',dinner:a.name+' chế giễu thành tích của '+b.name+' trong bữa ăn. Họ hàng chờ xem gia đình sẽ lắng nghe và giữ ranh giới ra sao.',bond:a.name+' và '+b.name+' vốn ít nói chuyện nay thường gặp nhau, muốn cùng theo đuổi một hoạt động riêng.',outsider:'Trong buổi gặp, '+a.name+' và '+b.name+' nghe lời nhận xét rằng con ngoài hôn nhân không thuộc về gia đình. Cần bàn cách ứng xử và quyền được tôn trọng, không mặc định ai là người xấu.',birthday:'Trong sinh nhật của '+b.name+', sự chú ý chuyển sang thành tích đã có trong hồ sơ của '+(find(l,e.ach)||a).name+'. Người còn lại cảm thấy mình bị lu mờ.',university:a.name+' và '+b.name+' đang có kết quả học tập khác nhau: '+E.EDU[a.person.edu||0]+' và '+E.EDU[b.person.edu||0]+'. So sánh trong gia đình khiến người chưa đạt mục tiêu muốn bàn hướng đi tiếp.',romance:a.name+' và '+b.name+' cùng để ý '+e.outsider+', một người trưởng thành ngoài gia đình. Người ấy có lựa chọn riêng; không ai được cha mẹ quyết định tình cảm thay.',venture:a.name+' và '+b.name+' muốn cùng góp vốn từ tiền riêng mở dự án kinh doanh. Một số người thân không đồng tình, hai người cần thỏa thuận rõ trách nhiệm.',scholarship:a.name+' và '+b.name+' cùng quan tâm cơ hội học bổng. Học lực, hồ sơ và lựa chọn ngành cần được tôn trọng; chưa ai tự được cấp bằng hoặc nhận học bổng chỉ vì cha mẹ giàu.',auction:a.name+' và '+b.name+' gặp nhau tại buổi giao lưu/đấu giá. Họ có thể giới thiệu mạng lưới cho nhau hoặc tiếp tục cạnh tranh. Chưa tự mua tài sản nào.',home:'Một trong hai người '+a.name+' và '+b.name+' đã được tặng nhà trong hồ sơ tài sản. Người còn lại muốn nghe lý do và bàn cách hỗ trợ theo nhu cầu.'};return t[e.type]||'';}
function familyEvent(l,r,log,manual){var s=state(l);if(s.eventAt===l.age||!manual&&s.eventAt!=null&&l.age-s.eventAt<3)return false;var es=eventChoices(l);if(!es.length)return false;var e=copy(U.pick(r,es));e.id='event908:'+l.id+':'+(++s.serial);e.at=l.age;e.done=false;e.outsiderSex=r()<.5?'M':'F';e.outsider=H.stranger(l,r,e.outsiderSex);e.choice=Math.floor(r()*3);s.event=e;s.eventAt=l.age;X.next(l,'familyEvent908',r,{event:e.id},{manual:!!manual});return true;}
X.menu('familyGathering908','Gặp gỡ và quan hệ giữa các nhánh con',adult,'Các câu chuyện dùng đúng những người con còn sống và thành tích/tài sản đang có. Không phải gia đình nào cũng có cạnh tranh kế nghiệp hoặc tiệc xa hoa.',function(l){return[{k:'gather',l:'Thu xếp một buổi gặp giữa các con',why:state(l).eventAt===l.age?'Đã có cuộc gặp năm nay':children(l).filter(function(p){return p.age>=10;}).length<2?'Cần ít nhất hai người con từ 10 tuổi':true,run:function(l,r,log){familyEvent(l,r,log,true);}}];},18,'Tình cảm & gia đình');
X.menu('familyEvent908','Một cuộc gặp giữa những người con',adult,function(l,d){var e=state(l).event;return e&&e.id===d.arg.event?eventText(l,e):'Cuộc gặp đã khép lại.';},function(l,a){var e=state(l).event;if(!e||e.id!==a.event||e.done||e.at!==l.age)return[];var pa=find(l,e.a),pb=find(l,e.b);if(!pa||!pb)return[];var out=[['listen','Lắng nghe riêng từng người, không so sánh'],['mediate','Cùng đặt ranh giới, thỏa thuận nhu cầu và trách nhiệm'],['ignore','Để các con tự xử lý, chưa can thiệp']].map(function(row){return{k:row[0],l:row[1],run:function(l,r,log){if(e.done)return;e.done=true;var delta=row[0]==='ignore'?-3:row[0]==='mediate'?7:4;if(e.type==='bond')delta=row[0]==='ignore'?2:8;if(e.type==='romance'){var chosen=e.choice===0?pa:e.choice===1?pb:null;if(chosen&&!chosen.person.married&&!chosen.person.partner){var npc=E.LIFE138.person(l,e.id+':outsider',e.outsider,e.outsiderSex||'F',l.birthYear+l.age-Math.max(18,Math.min(pa.age,pb.age)), 'người quen ngoài gia đình');npc.alive=true;chosen.person.romance908={id:npc.id,name:npc.name,since:l.age,status:'getting-to-know'};npc.events.push('Tự nguyện tìm hiểu '+chosen.name+' năm '+(l.birthYear+l.age));}else if(chosen)e.choice=2;log(e.outsider+(e.choice===0?' muốn tìm hiểu '+pa.name:e.choice===1?' muốn tìm hiểu '+pb.name:' không muốn hẹn hò với ai lúc này')+'. Gia đình không quyết định thay người ấy.','neutral');}relation(l,pa.id,pb.id,delta);[pa,pb].forEach(function(p){p.person.close=clamp((p.person.close||50)+(row[0]==='ignore'?-1:2));note(l,p,(row[0]==='ignore'?'Cuộc gặp còn khoảng cách':'Đã cùng đối thoại')+' với '+(p===pa?pb.name:pa.name));});H.mem(l,'Buổi gặp giữa '+pa.name+' và '+pb.name+': '+row[1]+'.',3);log(row[0]==='ignore'?'Các con tiếp tục có quan điểm riêng, khoảng cách chưa được tháo gỡ.':'Gia đình ghi nhận mong muốn của mỗi người. Quan hệ thay đổi qua đối thoại; tài sản và quyền học tập không bị tước đi.','neutral');}};});if(e.type==='inquiry')out.push({k:'investigate',l:'Cùng tìm hiểu hồ sơ về người con cần xác minh',run:function(l,r){if(e.done)return;e.done=true;X.next(l,'childClaims908',r);}});if(e.type==='venture')out.push({k:'joint',l:'Ủng hộ thỏa thuận góp vốn từ tiền riêng của hai con',run:function(l,r,log){if(e.done)return;e.done=true;if(!joint(l,pa,pb,r,log))log('Chưa đủ tiền riêng, còn dự án cũ hoặc một người chưa sẵn sàng. Không trừ tiền khi chưa lập được dự án.','neutral');}});return out;},18);
function projectYear(l,p,log){var q=profile(l,p),j=q.project;if(!j||j.status!=='active'||l.age<=j.at||j.lastAt===l.age)return;j.lastAt=l.age;var e=entity(l,j.cid);if(!e){j.status='closed';note(l,p,'Dự án kết thúc vì doanh nghiệp đã thay đổi');return;}var pass=j.rolls[j.progress]<U.clamp(.18+q.management/180+q.reputation/500,.08,.9);j.progress++;if(pass)j.score++;q.management=clamp(q.management+(pass?3:1));log(p.name+' báo cáo '+j.title+' năm '+j.progress+'/2: '+(pass?'đạt mục tiêu.':'cần điều chỉnh kế hoạch.'),'neutral');if(j.progress<2)return;j.status=j.score>=1?'completed':'failed';j.finished=l.age;q.reputation=clamp(q.reputation+(j.status==='completed'?6:-5));var returned=j.cost*(j.score===2?1.3:j.score===1?.9:.2);if(e.company){T.transaction(l,e.company,returned,'Thu hồi dự án kế nghiệp '+p.name);e.company.value+=returned;}else{e.family.value=Math.max(0,e.family.value+returned-j.cost);/* parents keep the proceeds; never player's cash */}j.returned=returned;note(l,p,'Kết thúc '+j.title+': '+j.score+'/2 mục tiêu, có báo cáo vốn thực');log('Dự án của '+p.name+' kết thúc, thu hồi '+H.money(l,returned)+(e.company?' về công ty.':' thuộc doanh nghiệp bố mẹ, không chuyển thành tiền cá nhân.')+' Năng lực và uy tín được cập nhật; chưa tự được bổ nhiệm.','neutral');}
function reviewYear(l,r,log){state(l).reviews.forEach(function(c){if(c.status!=='open'||l.age<c.due)return;c.status='closed';c.finished=l.age;if(!c.estate){c.result='dialogue';log('Gia đình hoàn tất buổi đối chiếu do '+c.name+' đề nghị. Mọi người ghi nhận nhu cầu và có thể chủ động sửa di chúc của chính mình; game không tự đổi phần của người khác.','neutral');return;}var sibs=people(l).filter(function(p){return (l.sibList||[]).includes(p.person)&&p.age>=18;}),donor=sibs.find(function(p){return p.person.savings158>l.base*.1&&relation(l,'self',p.id)>=50;});if(!donor||c.roll>=Math.min(.85,.35+c.evidence*.15)){c.result='unchanged';log('Yêu cầu hòa giải chưa được các bên đồng thuận hoặc không có tiền để bù phần chênh lệch; tài sản giữ nguyên.','neutral');return;}var amount=Math.min(l.base*.1,donor.person.savings158*.1);if(E.RELATIVE163.post(l,donor.person,-amount,'Tự nguyện hòa giải phần thừa kế','review908:'+c.at)){H.cash(l,amount,'Hòa giải thừa kế từ tiền thực của '+donor.name);c.amount=amount;c.result='settled';relation(l,'self',donor.id,4);log(donor.name+' đồng ý chuyển '+H.money(l,amount)+' từ tiền riêng để hòa giải; không tạo thêm di sản.','good');}});}
